  "sv.ref_claim_hint": { pt: "Pode usar um código nos primeiros 14 dias da sua conta.", en: "You can use a code within the first 14 days of your account.", zh: "您可以在账户创建后的头 14 天内使用邀请码。", fr: "Vous pouvez utiliser un code pendant les 14 premiers jours de votre compte." },
  "sv.confirming": { pt: "A confirmar…", en: "Confirming…", zh: "正在确认…", fr: "Confirmation…" },
