  "sv.how_it_works": { pt: "Como funciona?", en: "How does it work?", zh: "如何运作？", fr: "Comment ça marche ?" },
  "sv.ref_step1": { pt: "1. Envie a sua ligação ou o seu código a um amigo, uma empresa ou um profissional.", en: "1. Send your link or code to a friend, a business or a professional.", zh: "1. 把您的链接或邀请码发给朋友、企业或专业人士。", fr: "1. Envoyez votre lien ou votre code à un ami, une entreprise ou un professionnel." },
  "sv.ref_step2": { pt: "2. O amigo cria a conta e escreve o código (ou usa a ligação).", en: "2. Your friend creates an account and enters the code (or uses the link).", zh: "2. 朋友创建账户并输入邀请码（或使用链接）。", fr: "2. Votre ami crée un compte et indique le code (ou utilise le lien)." },
  "sv.ref_step3": { pt: "3. Quando o amigo pagar a primeira mensalidade, ganha {days} grátis na sua mensalidade.", en: "3. When your friend pays their first monthly fee, you get {days} free on your monthly fee.", zh: "3. 朋友首次支付月费后，您的月费可获赠 {days} 免费。", fr: "3. Quand votre ami paie sa première mensualité, vous gagnez {days} gratuits sur votre mensualité." },
  // Agentes no terreno
  "sv.saved": { pt: "Dados guardados.", en: "Details saved.", zh: "资料已保存。", fr: "Données enregistrées." },
  "sv.ag_sent": { pt: "Pedido enviado. A administração vai responder em breve.", en: "Request sent. The admins will reply soon.", zh: "申请已提交。管理员会尽快答复。", fr: "Demande envoyée. L'administration va bientôt répondre." },
  "sv.ag_title": { pt: "🤝 Agentes no terreno", en: "🤝 Field agents", zh: "🤝 实地代理", fr: "🤝 Agents de terrain" },
  "sv.ag_intro": { pt: "Trabalha numa praça (por exemplo, o Kapango) ou conhece pessoas sem telemóvel ou que não sabem usar a internet? Ajude-as a pôr anúncios de venda, troca ou leilão no Huambo Online e ganhe uma comissão sempre que um desses anúncios for vendido.", en: "Do you work at a market (for example, Kapango) or know people without a phone or who don't know how to use the internet? Help them post sale, trade or auction listings on Huambo Online and earn a commission every time one of those listings is sold.", zh: "您在市场（例如 Kapango）工作，或认识没有手机、不会上网的人吗？帮助他们在 Huambo Online 上发布出售、交换或拍卖信息，每当其中一条信息售出，您就能获得佣金。", fr: "Vous travaillez dans un marché (par exemple, Kapango) ou connaissez des personnes sans téléphone ou qui ne savent pas utiliser internet ? Aidez-les à publier des annonces de vente, d'échange ou d'enchère sur Huambo Online et touchez une commission chaque fois qu'une de ces annonces est vendue." },
  "sv.ag_step1": { pt: "1. Peça para ser agente (escolha a sua praça). A administração confirma.", en: "1. Apply to become an agent (choose your market). The admins confirm.", zh: "1. 申请成为代理（选择您的市场）。由管理员确认。", fr: "1. Postulez pour devenir agent (choisissez votre marché). L'administration confirme." },
  "sv.ag_step2": { pt: "2. Recebe um código, por exemplo AG1001.", en: "2. You receive a code, for example AG1001.", zh: "2. 您会收到一个代码，例如 AG1001。", fr: "2. Vous recevez un code, par exemple AG1001." },
  "sv.ag_step3": { pt: "3. Ajude o vendedor a publicar na conta dele e peça-lhe para escrever o seu código.", en: "3. Help the seller publish from their own account and ask them to enter your code.", zh: "3. 帮助卖家用其本人账户发布，并请他填写您的代码。", fr: "3. Aidez le vendeur à publier depuis son propre compte et demandez-lui d'indiquer votre code." },
  "sv.ag_step4": { pt: "4. Quando o vendedor marcar o anúncio como vendido, ganha a sua parte do valor da venda.", en: "4. When the seller marks the listing as sold, you earn your share of the sale value.", zh: "4. 卖家将信息标记为已售出后，您即可获得成交金额中属于您的份额。", fr: "4. Quand le vendeur marque l'annonce comme vendue, vous gagnez votre part du montant de la vente." },
  "sv.ag_step5": { pt: "5. Depois de a administração confirmar, o valor entra no seu saldo e pode levantar.", en: "5. Once the admins confirm, the amount goes into your balance and you can withdraw it.", zh: "5. 管理员确认后，金额会计入您的余额，您可以提现。", fr: "5. Une fois confirmé par l'administration, le montant va dans votre solde et vous pouvez le retirer." },
