  "sv.business": { pt: "Empresa", en: "Business", zh: "企业", fr: "Entreprise" },
  "sv.ver_biz_doc": { pt: "Alvará, NIF ou certidão comercial", en: "Business licence, tax number or commercial certificate", zh: "营业执照、税号或商业登记证明", fr: "Licence commerciale, numéro fiscal ou certificat commercial" },
