  "sv.aga_bad_pct": { pt: "Escreva a percentagem do agente (de 0 a 20).", en: "Enter the agent's percentage (from 0 to 20).", zh: "请填写代理的百分比（0 到 20）。", fr: "Indiquez le pourcentage de l'agent (de 0 à 20)." },
  "sv.aga_rules_saved": { pt: "Regras dos agentes guardadas.", en: "Agent rules saved.", zh: "代理规则已保存。", fr: "Règles des agents enregistrées." },
  "sv.aga_pct": { pt: "Percentagem do agente em cada venda (%)", en: "Agent's percentage on each sale (%)", zh: "代理在每笔销售中的百分比（%）", fr: "Pourcentage de l'agent sur chaque vente (%)" },
  "sv.aga_pct_a11y": { pt: "Percentagem do agente (%)", en: "Agent's percentage (%)", zh: "代理百分比（%）", fr: "Pourcentage de l'agent (%)" },
  "sv.aga_pct_hint": { pt: "Quando um anúncio feito com o código do agente é vendido, o agente ganha esta percentagem do valor da venda. Antes de confirmar, veja se o vendedor já pagou a comissão da venda.", en: "When a listing made with the agent's code is sold, the agent earns this percentage of the sale value. Before confirming, check whether the seller has already paid the sale commission.", zh: "使用代理代码发布的信息售出后，代理可获得成交金额的这一百分比。确认前，请查看卖方是否已支付销售佣金。", fr: "Quand une annonce faite avec le code de l'agent est vendue, l'agent gagne ce pourcentage du montant de la vente. Avant de confirmer, vérifiez si le vendeur a déjà payé la commission de vente." },
