  // Combustível: reservas, postos e gestão
  "sv.fu_need_proof": { pt: "Junte a fotografia do comprovativo de pagamento.", en: "Attach a photo of the payment receipt.", zh: "请附上付款凭证照片。", fr: "Joignez une photo du justificatif de paiement." },
  "sv.fu_need_ref": { pt: "Escreva a referência ou o número da operação (como está no comprovativo).", en: "Enter the reference or transaction number (as on the receipt).", zh: "请填写参考号或交易号（与凭证上一致）。", fr: "Indiquez la référence ou le numéro de transaction (tel qu'il figure sur le justificatif)." },
