  "sv.fu_pay_station": { pt: "1. Pague {v} ao posto{by}", en: "1. Pay {v} to the station{by}", zh: "1. 向加油站支付 {v}{by}", fr: "1. Payez {v} à la station{by}" },
  "sv.fu_only_station": { pt: "⚠️ Pague só para a conta do posto mostrada aqui. Nunca pague a quem lhe ligar a pedir outra conta.", en: "⚠️ Only pay into the station account shown here. Never pay anyone who calls asking for a different account.", zh: "⚠️ 只向此处显示的加油站账户付款。切勿向打电话要求换账户的人付款。", fr: "⚠️ Payez uniquement sur le compte de la station affiché ici. Ne payez jamais quelqu'un qui appelle en demandant un autre compte." },
