  "sv.ve_my_empty": { pt: "Ainda não fez reservas nem encomendas.", en: "You haven't made any bookings or orders yet.", zh: "您还没有任何预订或订单。", fr: "Vous n'avez encore fait aucune réservation ni commande." },
  "sv.ve_proof_sent": { pt: "Comprovativo enviado. O estabelecimento vai confirmar o pagamento.", en: "Receipt sent. The venue will confirm the payment.", zh: "凭证已发送。商家会确认付款。", fr: "Justificatif envoyé. L'établissement va confirmer le paiement." },
