  "sv.ve_confirming": { pt: "O estabelecimento está a confirmar o pagamento na conta dele. Pode ir: lá verificam o QR e o comprovativo.", en: "The venue is confirming the payment in its account. You can go: they'll check the QR and the receipt there.", zh: "商家正在其账户中确认付款。您可以前往，他们会在现场核对二维码和凭证。", fr: "L'établissement confirme le paiement sur son compte. Vous pouvez y aller : ils vérifieront le QR et le justificatif sur place." },
  "sv.ve_call": { pt: "📞 Ligar ao estabelecimento", en: "📞 Call the venue", zh: "📞 致电商家", fr: "📞 Appeler l'établissement" },
  "sv.ve_pay_place": { pt: "1. Pague {v} ao estabelecimento{by}", en: "1. Pay {v} to the venue{by}", zh: "1. 向商家支付 {v}{by}", fr: "1. Payez {v} à l'établissement{by}" },
  "sv.ve_only_account": { pt: "⚠️ Pague só para a conta mostrada aqui. Nunca pague a quem lhe ligar a pedir outra conta.", en: "⚠️ Only pay into the account shown here. Never pay anyone who calls asking for a different account.", zh: "⚠️ 只向此处显示的账户付款。切勿向打电话要求换账户的人付款。", fr: "⚠️ Payez uniquement sur le compte affiché ici. Ne payez jamais quelqu'un qui appelle en demandant un autre compte." },
