  "sv.ve_pay_place_ok": { pt: "O cliente pode pagar no local", en: "The customer can pay on site", zh: "客户可以现场付款", fr: "Le client peut payer sur place" },
  "sv.ve_prepay_ok": { pt: "O cliente pode pagar adiantado (para a minha conta)", en: "The customer can pay in advance (into my account)", zh: "客户可以预付款（付到我的账户）", fr: "Le client peut payer d'avance (sur mon compte)" },
  "sv.ve_hold": { pt: "Tolerância: quantos minutos guardo a reserva depois da hora? (15 a 1440)", en: "Grace period: how many minutes do I hold the booking after the time? (15 to 1440)", zh: "宽限时间：预约时间过后保留预订多少分钟？（15 至 1440）", fr: "Délai de tolérance : combien de minutes je maintiens la réservation après l'heure ? (15 à 1440)" },
